const s = $input.first().json;
const total   = parseInt(s.total_trades) || 0;
const wins    = parseInt(s.winning_trades) || 0;
const losses  = parseInt(s.losing_trades) || 0;
const winRate = total > 0 ? ((wins / total) * 100).toFixed(1) : '0.0';
const date    = new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', day:'2-digit', month:'short', year:'numeric' });

const pnlEmoji = parseFloat(s.total_pnl) >= 0 ? '🟢' : '🔴';

const report = `📊 *DAILY TRADE REPORT*
📅 ${date}
${'─'.repeat(28)}
📈 Total Trades: ${total}
✅ Winners: ${wins} | ❌ Losers: ${losses}
🎯 Win Rate: ${winRate}%
${'─'.repeat(28)}
${pnlEmoji} Total P&L: ₹${parseFloat(s.total_pnl).toFixed(2)}
🏆 Best Trade: +₹${parseFloat(s.best_trade).toFixed(2)}
💸 Worst Trade: ₹${parseFloat(s.worst_trade).toFixed(2)}
📊 Avg Gain: +${s.avg_gain_pct}%
📉 Avg Loss: ${s.avg_loss_pct}%
${'─'.repeat(28)}
🤖 Chartink Smart Trade Tracker`;

return [{ json: { ...s, report, win_rate: winRate, date } }];
